/* === 牌スート色・演出用クラス（ルール変更なし） === */
const SEAT_PANEL_ID = {
  [SEAT_SOUTH]: 'seat-east',
  [SEAT_WEST]: 'seat-north',
  [SEAT_NORTH]: 'seat-west'
};

function tileSuitClass(tileIndex) {
  if (tileIndex >= 0 && tileIndex <= 8) return 'tile--man';
  if (tileIndex >= 9 && tileIndex <= 17) return 'tile--pin';
  if (tileIndex >= 18 && tileIndex <= 26) return 'tile--sou';
  return 'tile--honor';
}

function applyTileSuitClass(el, tileIndex) {
  el.classList.remove('tile--man', 'tile--pin', 'tile--sou', 'tile--honor');
  el.classList.add(tileSuitClass(tileIndex));
  el.dataset.tile = String(tileIndex);
}

function flashTileAnim(el) {
  if (!el) return;
  el.classList.remove('tile--flash');
  void el.offsetWidth;
  el.classList.add('tile--flash');
  window.setTimeout(function () { el.classList.remove('tile--flash'); }, 700);
}

function flashLastRiverTile(seat) {
  const riverEl = [els.riverSouth, els.riverEast, els.riverNorth, els.riverWest][seat];
  if (!riverEl || !riverEl.lastElementChild) return;
  flashTileAnim(riverEl.lastElementChild);
}

function flashHumanDrawnTile() {
  if (!els.handSouth) return;
  const drawn = els.handSouth.querySelector('.tile.drawn');
  if (drawn) flashTileAnim(drawn);
}

function pulseMessage() {
  els.message.classList.remove('msg--pulse');
  void els.message.offsetWidth;
  els.message.classList.add('msg--pulse');
}

function syncPhaseUi() {
  document.body.className = document.body.className.replace(/\bphase--\S+/g, '').trim();
  if (state.phase) document.body.classList.add('phase--' + state.phase);
  Object.keys(SEAT_PANEL_ID).forEach(function (seatKey) {
    const panelId = SEAT_PANEL_ID[seatKey];
    const panel = document.getElementById(panelId);
    if (!panel) return;
    panel.classList.add('seat--cpu');
    if (!panel.querySelector('.cpu-led')) {
      const led = document.createElement('motion');
      led.className = 'cpu-led';
      led.setAttribute('aria-hidden', 'true');
      led.innerHTML = '<span class="cpu-led-dot"></span><span class="cpu-led-dot"></span><span class="cpu-led-dot"></span><span>THINK</span>';
      panel.appendChild(led);
    }
    const thinking = state.phase === 'cpu_think' && state.current === Number(seatKey);
    panel.classList.toggle('seat--thinking', thinking);
  });
}

